from pathlib import Path

p = Path('src/routes/match.tsx')
s = p.read_text()

def rep(old, new, label):
    global s
    if old not in s:
        raise SystemExit(f'anchor not found: {label}')
    s = s.replace(old, new, 1)

rep('type Step = "players" | "teams" | "scoring" | "category" | "type" | "setup" | "length" | "play" | "result";',
    'type Step = "players" | "teams" | "scoring" | "category" | "type" | "setup" | "approach-setup" | "length" | "play" | "result";', 'step')
rep('type Hole = { challenge: Challenge; winner: HoleWinner; blueStrokes?: number; redStrokes?: number; bluePoints?: number; redPoints?: number };\ntype ShortGameLie = "fairway" | "rough" | "bunker";',
    'type ApproachResult = { longitudinalDirection: "short" | "long"; longitudinal: number; lateralDirection: "left" | "right"; lateral: number; proximity: number };\ntype Hole = { challenge: Challenge; winner: HoleWinner; blueStrokes?: number; redStrokes?: number; bluePoints?: number; redPoints?: number; blueApproach?: ApproachResult; redApproach?: ApproachResult };\ntype ShortGameLie = "fairway" | "rough" | "bunker";\ntype ApproachRangeId = "50-100" | "100-150" | "150-200" | "custom";', 'types')
rep('{ id: "approach", title: "Inspel", subtitle: "Approach", description: "Precision, längdkontroll och bollflykt." },',
    '{ id: "approach", title: "Inspel", subtitle: "Approach", description: "Closest to Pin med varierade avstånd och exakt proximity." },', 'approach category desc')
rep('''  approach: [\n    { id: "closest", title: "Closest to Pin", description: "SG4 väljer avstånd. Närmast flaggan vinner." },\n    { id: "control", title: "Distance Control", description: "Bäst längdkontroll mot ett genererat målavstånd vinner." },\n    { id: "shape", title: "Shot Shaping", description: "Avstånd plus draw eller fade genereras inför varje hål." },\n  ],''',
    '''  approach: [\n    { id: "closest", title: "Closest to Pin", description: "Samma målavstånd för båda. Närmast flaggan vinner hålet." },\n  ],''', 'approach types')
rep('function bunkerLimit(length: MatchLength) { return length === 5 ? 1 : length === 9 ? 2 : 4; }', '''function bunkerLimit(length: MatchLength) { return length === 5 ? 1 : length === 9 ? 2 : 4; }\nfunction approachRangeBounds(id: ApproachRangeId, customMin: number, customMax: number): [number, number] {\n  if (id === "50-100") return [50, 100];\n  if (id === "100-150") return [100, 150];\n  if (id === "150-200") return [150, 200];\n  return [Math.min(customMin, customMax), Math.max(customMin, customMax)];\n}\nfunction generateApproachDistances(length: MatchLength, selected: ApproachRangeId[], customMin: number, customMax: number) {\n  const ranges = selected.length ? selected : (["100-150"] as ApproachRangeId[]);\n  const order = [...ranges].sort(() => Math.random() - 0.5);\n  const out: number[] = [];\n  for (let i = 0; i < length; i++) {\n    const id = order[i % order.length];\n    const [min, max] = approachRangeBounds(id, customMin, customMax);\n    let value = rand(min, max);\n    let tries = 0;\n    while (i > 0 && Math.abs(value - out[i - 1]) < 8 && tries < 12) { value = rand(min, max); tries++; }\n    out.push(value);\n  }\n  return out;\n}''', 'approach helpers')
rep('function generateChallenge(category: MatchCategory, typeId: string, mode: MatchMode, shortGameLies: ShortGameLie[] = ["fairway", "rough", "bunker"]): Challenge {',
    'function generateChallenge(category: MatchCategory, typeId: string, mode: MatchMode, shortGameLies: ShortGameLie[] = ["fairway", "rough", "bunker"], approachDistance?: number): Challenge {', 'challenge signature')
rep('''  if (category === "approach") {\n    const d = rand(typeId === "control" ? 60 : 80, typeId === "shape" ? 170 : 180);\n    if (typeId === "shape") return { eyebrow: pick(["Draw", "Fade"] as const), title: `${d} m`, detail: `Rätt bollflykt + närmast flaggan vinner${suffix}` };\n    if (typeId === "control") return { eyebrow: "Distance Control", title: `${d} m`, detail: `Bäst längdkontroll vinner${suffix}` };\n    return { eyebrow: "Closest to Pin", title: `${d} m`, detail: `Närmast flaggan vinner${suffix}` };\n  }''',
    '''  if (category === "approach") {\n    const d = approachDistance ?? rand(100, 150);\n    return { eyebrow: "Closest to Pin", title: `${d} m`, detail: `Samma mål för båda · närmast flaggan vinner${suffix}` };\n  }''', 'approach challenge')
rep('const [shortGameLies, setShortGameLies] = useState<ShortGameLie[]>([]);', '''const [shortGameLies, setShortGameLies] = useState<ShortGameLie[]>([]);\n  const [approachRanges, setApproachRanges] = useState<ApproachRangeId[]>([]);\n  const [approachCustomMin, setApproachCustomMin] = useState(50);\n  const [approachCustomMax, setApproachCustomMax] = useState(200);\n  const [approachTurn, setApproachTurn] = useState<"blue" | "red">("blue");\n  const [approachLongDirection, setApproachLongDirection] = useState<"short" | "long">("short");\n  const [approachLong, setApproachLong] = useState(0);\n  const [approachLateralDirection, setApproachLateralDirection] = useState<"left" | "right">("left");\n  const [approachLateral, setApproachLateral] = useState(0);''', 'approach state')
rep('const isShortGame = category === "around-the-green";\n  const isScoredHole = isPutting || isShortGame;\n  const unitLabel = isScoredHole ? "Hål" : "Omgång";\n  const setupValid = shortGameLies.length > 0;',
    'const isShortGame = category === "around-the-green";\n  const isApproach = category === "approach";\n  const isScoredHole = isPutting || isShortGame;\n  const unitLabel = isPutting || isShortGame || isApproach ? "Hål" : "Omgång";\n  const setupValid = shortGameLies.length > 0;\n  const approachSetupValid = approachRanges.length > 0 && (!approachRanges.includes("custom") || (approachCustomMin >= 50 && approachCustomMax <= 250 && approachCustomMin < approachCustomMax));\n  const approachProximityPreview = Math.sqrt(approachLong * approachLong + approachLateral * approachLateral);', 'derived')
rep('function toggleShortGameLie(id: ShortGameLie) { setShortGameLies((items) => items.includes(id) ? items.filter((x) => x !== id) : [...items, id]); }',
    'function toggleShortGameLie(id: ShortGameLie) { setShortGameLies((items) => items.includes(id) ? items.filter((x) => x !== id) : [...items, id]); }\n  function toggleApproachRange(id: ApproachRangeId) { setApproachRanges((items) => items.includes(id) ? items.filter((x) => x !== id) : [...items, id]); }\n  function resetApproachInput() { setApproachLongDirection("short"); setApproachLong(0); setApproachLateralDirection("left"); setApproachLateral(0); }', 'toggle range')
rep('''    const nextHoles = isShortGame\n      ? generateShortGameLieSequence(matchLength, shortGameLies).map((lie) => ({ challenge: generateChallenge(category, matchType, mode, [lie]), winner: null as HoleWinner }))\n      : Array.from({ length: matchLength }, () => ({ challenge: generateChallenge(category, matchType, mode, shortGameLies), winner: null as HoleWinner }));\n    setHoles(nextHoles);\n    setHoleIndex(0); setBlueStrokes(1); setRedStrokes(1); setBluePoints(null); setRedPoints(null); setFinalText(""); setIsSubmitting(false); setTransitionMessage(null); setEditingHoleIndex(null); setReturnHoleIndex(null); setStep("play");''',
    '''    const nextHoles = isShortGame\n      ? generateShortGameLieSequence(matchLength, shortGameLies).map((lie) => ({ challenge: generateChallenge(category, matchType, mode, [lie]), winner: null as HoleWinner }))\n      : isApproach\n        ? generateApproachDistances(matchLength, approachRanges, approachCustomMin, approachCustomMax).map((distance) => ({ challenge: generateChallenge(category, matchType, mode, shortGameLies, distance), winner: null as HoleWinner }))\n        : Array.from({ length: matchLength }, () => ({ challenge: generateChallenge(category, matchType, mode, shortGameLies), winner: null as HoleWinner }));\n    setHoles(nextHoles);\n    setHoleIndex(0); setBlueStrokes(1); setRedStrokes(1); setBluePoints(null); setRedPoints(null); setApproachTurn("blue"); resetApproachInput(); setFinalText(""); setIsSubmitting(false); setTransitionMessage(null); setEditingHoleIndex(null); setReturnHoleIndex(null); setStep("play");''', 'start match')
rep('''  function recordShortGame() {\n    if (isSubmitting || bluePoints === null || redPoints === null) return;\n    setIsSubmitting(true);\n    const registered = holeIndex;\n    const winner: Exclude<HoleWinner, null> = bluePoints > redPoints ? "blue" : redPoints > bluePoints ? "red" : "tie";\n    const next = holes.map((h, i) => i === registered ? { ...h, winner, bluePoints, redPoints } : h);\n    if (editingHoleIndex !== null) { finishScoredEdit(next, registered); return; }\n    setTransitionMessage(`${unitLabel} ${registered + 1} registrerad`);\n    window.setTimeout(() => { advance(next); setTransitionMessage(null); setIsSubmitting(false); }, 380);\n  }''',
    '''  function recordShortGame() {\n    if (isSubmitting || bluePoints === null || redPoints === null) return;\n    setIsSubmitting(true);\n    const registered = holeIndex;\n    const winner: Exclude<HoleWinner, null> = bluePoints > redPoints ? "blue" : redPoints > bluePoints ? "red" : "tie";\n    const next = holes.map((h, i) => i === registered ? { ...h, winner, bluePoints, redPoints } : h);\n    if (editingHoleIndex !== null) { finishScoredEdit(next, registered); return; }\n    setTransitionMessage(`${unitLabel} ${registered + 1} registrerad`);\n    window.setTimeout(() => { advance(next); setTransitionMessage(null); setIsSubmitting(false); }, 380);\n  }\n  function recordApproach() {\n    if (isSubmitting) return;\n    const result: ApproachResult = { longitudinalDirection: approachLongDirection, longitudinal: approachLong, lateralDirection: approachLateralDirection, lateral: approachLateral, proximity: Math.sqrt(approachLong * approachLong + approachLateral * approachLateral) };\n    if (approachTurn === "blue") {\n      setHoles((items) => items.map((h, i) => i === holeIndex ? { ...h, blueApproach: result } : h));\n      setApproachTurn("red"); resetApproachInput(); return;\n    }\n    const blue = holes[holeIndex]?.blueApproach;\n    if (!blue) return;\n    setIsSubmitting(true);\n    const winner: Exclude<HoleWinner, null> = blue.proximity < result.proximity ? "blue" : result.proximity < blue.proximity ? "red" : "tie";\n    const next = holes.map((h, i) => i === holeIndex ? { ...h, redApproach: result, winner } : h);\n    setTransitionMessage(`${unitLabel} ${holeIndex + 1} registrerad`);\n    window.setTimeout(() => { advance(next); setApproachTurn("blue"); resetApproachInput(); setTransitionMessage(null); setIsSubmitting(false); }, 380);\n  }''', 'record approach')
rep('setScoringMode("match"); setMatchLength(5); setHoles([]); setHoleIndex(0); setFinalText(""); setBlueStrokes(1); setRedStrokes(1); setBluePoints(null); setRedPoints(null); setShortGameLies([]); setIsSubmitting(false);',
    'setScoringMode("match"); setMatchLength(5); setHoles([]); setHoleIndex(0); setFinalText(""); setBlueStrokes(1); setRedStrokes(1); setBluePoints(null); setRedPoints(null); setShortGameLies([]); setApproachRanges([]); setApproachCustomMin(50); setApproachCustomMax(200); setApproachTurn("blue"); resetApproachInput(); setIsSubmitting(false);', 'reset')
rep('else if (step === "setup") setStep("category");\n    else if (step === "length") setStep(isShortGame ? "setup" : category === "off-the-tee" ? "category" : (category === "approach" && matchType === "closest" ? "type" : "scoring"));',
    'else if (step === "setup") setStep("category");\n    else if (step === "approach-setup") setStep("category");\n    else if (step === "length") setStep(isShortGame ? "setup" : isApproach ? "approach-setup" : category === "off-the-tee" ? "category" : "scoring");', 'back')
rep('const stepLabel = step === "players" ? "1 · Spelform & spelare" : step === "teams" ? "2 · Lag" : step === "scoring" ? "Spelsätt" : step === "category" ? "Kategori" : step === "type" ? "Spel" : step === "setup" ? "Närspel · Setup" : "Matchlängd";',
    'const stepLabel = step === "players" ? "1 · Spelform & spelare" : step === "teams" ? "2 · Lag" : step === "scoring" ? "Spelsätt" : step === "category" ? "Kategori" : step === "type" ? "Spel" : step === "setup" ? "Närspel · Setup" : step === "approach-setup" ? "Inspel · Avstånd" : "Matchlängd";', 'step label')
rep('''setCategory(i.id); if (i.id === "around-the-green") { setMatchType("closest"); setShortGameLies([]); } else if (i.id === "off-the-tee") { setMatchType("fairway"); setScoringMode("match"); } else setMatchType(null);''',
    '''setCategory(i.id); if (i.id === "around-the-green") { setMatchType("closest"); setShortGameLies([]); } else if (i.id === "off-the-tee") { setMatchType("fairway"); setScoringMode("match"); } else if (i.id === "approach") { setMatchType("closest"); setScoringMode("match"); setApproachRanges([]); } else setMatchType(null);''', 'category click')
rep('''onClick={() => { if (category === "around-the-green" || category === "off-the-tee") setScoringMode("match"); setStep(category === "around-the-green" ? "setup" : category === "off-the-tee" ? "length" : "type"); }}''',
    '''onClick={() => { if (category === "around-the-green" || category === "off-the-tee" || category === "approach") setScoringMode("match"); setStep(category === "around-the-green" ? "setup" : category === "approach" ? "approach-setup" : category === "off-the-tee" ? "length" : "type"); }}''', 'category next')
rep('{step === "type" && category && !isShortGame ? <>', '{step === "type" && category && !isShortGame && !isApproach ? <>', 'hide approach type')

approach_setup_ui = '''\n    {step === "approach-setup" && isApproach ? <><section className="mt-5"><p className="text-[10px] font-bold uppercase text-slate-500">Inspel · Closest to Pin</p><h1 className="mt-1 font-display text-4xl">Välj avstånd</h1><p className="mt-2 text-sm text-slate-600">Välj ett eller flera intervall. SG4 varierar avstånden mellan valda intervall.</p></section><div className="mt-5 grid grid-cols-2 gap-3">{([[["50-100","50–100 m"],["100-150","100–150 m"],["150-200","150–200 m"],["custom","Eget intervall"]]] as const)[0].map(([id,label]) => { const active = approachRanges.includes(id); return <button key={id} onClick={() => toggleApproachRange(id)} className={`rounded-3xl border p-5 text-left ${active ? selectedGlass : glass}`}><span className="font-display text-2xl">{label}</span>{active ? <Check className="mt-2 h-5 w-5 text-blue-600" /> : null}</button>; })}</div>{approachRanges.includes("custom") ? <div className={`mt-4 rounded-3xl border p-4 ${glass}`}><p className="text-[10px] font-bold uppercase tracking-[0.14em] text-slate-500">Eget intervall · 50–250 m</p><div className="mt-3 grid grid-cols-2 gap-3"><label className="text-xs font-bold text-slate-600">Min<input type="number" min={50} max={249} value={approachCustomMin} onChange={(e) => setApproachCustomMin(Math.max(50, Math.min(249, Number(e.target.value) || 50)))} className="mt-1 w-full rounded-2xl border border-slate-300 bg-white/80 px-3 py-3 text-lg font-bold outline-none" /></label><label className="text-xs font-bold text-slate-600">Max<input type="number" min={51} max={250} value={approachCustomMax} onChange={(e) => setApproachCustomMax(Math.max(51, Math.min(250, Number(e.target.value) || 250)))} className="mt-1 w-full rounded-2xl border border-slate-300 bg-white/80 px-3 py-3 text-lg font-bold outline-none" /></label></div></div> : null}<button disabled={!approachSetupValid} onClick={() => setStep("length")} className="mt-5 flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 py-4 font-display text-xl text-white disabled:opacity-30">Nästa <ChevronRight className="h-5 w-5" /></button></> : null}\n'''
rep('\n    {step === "length" && selectedType ? <>', approach_setup_ui + '\n    {step === "length" && selectedType ? <>', 'insert approach setup UI')

approach_play = '''isApproach ? <section className="mt-5"><div className="text-center"><p className={`text-[10px] font-bold uppercase tracking-[0.16em] ${approachTurn === "blue" ? "text-blue-600" : "text-red-600"}`}>{current.challenge.title} · {(approachTurn === "blue" ? blueLabel : redLabel).toUpperCase()}S TUR</p><h2 className="mt-1 font-display text-2xl">Registrera miss</h2>{approachTurn === "red" && current.blueApproach ? <p className="mt-1 text-[10px] font-bold text-blue-700">{blueLabel}: {current.blueApproach.proximity.toFixed(1)} m från flaggan</p> : null}</div><div className={`mt-3 rounded-[26px] border p-4 ${approachTurn === "blue" ? blueGlass : redGlass}`}><p className="text-[10px] font-bold uppercase text-slate-500">Längdmiss</p><div className="mt-2 grid grid-cols-2 gap-2"><button onClick={() => setApproachLongDirection("short")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLongDirection === "short" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Kort</button><button onClick={() => setApproachLongDirection("long")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLongDirection === "long" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Lång</button></div><div className="mt-3 flex items-center justify-between gap-3"><button onClick={() => setApproachLong(Math.max(0, approachLong - 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Minus className="h-4 w-4" /></button><div className="text-center"><p className="font-display text-4xl">{approachLong}</p><p className="text-[9px] font-bold uppercase text-slate-500">meter</p></div><button onClick={() => setApproachLong(Math.min(100, approachLong + 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Plus className="h-4 w-4" /></button></div><p className="mt-4 text-[10px] font-bold uppercase text-slate-500">Sidmiss</p><div className="mt-2 grid grid-cols-2 gap-2"><button onClick={() => setApproachLateralDirection("left")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLateralDirection === "left" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Vänster</button><button onClick={() => setApproachLateralDirection("right")} className={`rounded-2xl border py-3 text-sm font-bold ${approachLateralDirection === "right" ? "border-slate-900 bg-slate-900 text-white" : "border-slate-300 bg-white/70"}`}>Höger</button></div><div className="mt-3 flex items-center justify-between gap-3"><button onClick={() => setApproachLateral(Math.max(0, approachLateral - 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Minus className="h-4 w-4" /></button><div className="text-center"><p className="font-display text-4xl">{approachLateral}</p><p className="text-[9px] font-bold uppercase text-slate-500">meter</p></div><button onClick={() => setApproachLateral(Math.min(100, approachLateral + 1))} className="flex h-11 w-11 items-center justify-center rounded-full border border-slate-300 bg-white/80"><Plus className="h-4 w-4" /></button></div><div className="mt-4 rounded-2xl bg-white/70 p-3 text-center"><p className="text-[9px] font-bold uppercase text-slate-500">Proximity</p><p className="font-display text-3xl">{approachProximityPreview.toFixed(1)} m</p></div></div><button disabled={isSubmitting} onClick={recordApproach} className="mt-3 flex w-full items-center justify-center gap-2 rounded-2xl bg-slate-950 py-4 font-display text-xl text-white disabled:opacity-30">{approachTurn === "blue" ? `Spara ${blueLabel}` : `Registrera ${redLabel}`} <ChevronRight className="h-5 w-5" /></button></section> : '''
rep('''isShortGame ? <section className="mt-5">''', '''isShortGame ? <section className="mt-5">''', 'noop shortgame anchor check')
# Replace the ternary handoff from shortgame to generic winner section
rep('''</button></section> : <section className="mt-5"><div className="text-center"><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-slate-500">2 · Registrering</p><h2 className="mt-1 font-display text-2xl">Vem vann?</h2>''',
    '''</button></section> : ''' + approach_play + '''<section className="mt-5"><div className="text-center"><p className="text-[9px] font-bold uppercase tracking-[0.16em] text-slate-500">2 · Registrering</p><h2 className="mt-1 font-display text-2xl">Vem vann?</h2>''', 'approach play UI')

# Scorecard: show proximity instead of blanks for approach
rep('const blueValue = isShortGame ? h.bluePoints : h.blueStrokes; const redValue = isShortGame ? h.redPoints : h.redStrokes;',
    'const blueValue = isShortGame ? h.bluePoints : isApproach ? h.blueApproach?.proximity : h.blueStrokes; const redValue = isShortGame ? h.redPoints : isApproach ? h.redApproach?.proximity : h.redStrokes;', 'scorecard blue values')
# second occurrence
if 'const blueValue = isShortGame ? h.bluePoints : h.blueStrokes; const redValue = isShortGame ? h.redPoints : h.redStrokes;' in s:
    s = s.replace('const blueValue = isShortGame ? h.bluePoints : h.blueStrokes; const redValue = isShortGame ? h.redPoints : h.redStrokes;', 'const blueValue = isShortGame ? h.bluePoints : isApproach ? h.blueApproach?.proximity : h.blueStrokes; const redValue = isShortGame ? h.redPoints : isApproach ? h.redApproach?.proximity : h.redStrokes;', 1)
s = s.replace('{typeof blueValue === "number" ? isShortGame ? `${blueValue}p` : blueValue : "–"}', '{typeof blueValue === "number" ? isShortGame ? `${blueValue}p` : isApproach ? `${blueValue.toFixed(1)}m` : blueValue : "–"}', 1)
s = s.replace('{typeof redValue === "number" ? isShortGame ? `${redValue}p` : redValue : "–"}', '{typeof redValue === "number" ? isShortGame ? `${redValue}p` : isApproach ? `${redValue.toFixed(1)}m` : redValue : "–"}', 1)
s = s.replace('>{isShortGame ? "Poäng" : unitLabel}</div>', '>{isShortGame ? "Poäng" : isApproach ? "Närhet" : unitLabel}</div>', 1)

p.write_text(s)
print('patched match.tsx')
